{
  "name": "csv-toolkit",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "test": "node --test test/"
  }
}

/**
 * Minimal CSV parsing for simple, unquoted comma-separated data.
 */

/**
 * Split a single CSV line into trimmed fields.
 * An empty line yields an empty array.
 */
export function parseLine(line: string): string[] {
  if (line === "") return [];
  return line.split(",").map((field) => field.trim());
}

/**
 * Parse CSV text into rows of fields.
 * Lines are separated by `\n` or `\r\n`; blank lines are skipped.
 */
export function parse(input: string): string[][] {
  return input
    .split(/\r?\n/)
    .map(parseLine)
    .filter((fields) => fields.length > 0);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { parse, parseLine } from "../src/parse.ts";

test("parseLine splits a simple line into fields", () => {
  assert.deepEqual(parseLine("a,b,c"), ["a", "b", "c"]);
});

test("parseLine trims surrounding whitespace", () => {
  assert.deepEqual(parseLine(" a , b ,c "), ["a", "b", "c"]);
});

test("parseLine on an empty line yields an empty array", () => {
  assert.deepEqual(parseLine(""), []);
});

test("parse splits multiple lines into rows", () => {
  assert.deepEqual(parse("a,b\nc,d"), [
    ["a", "b"],
    ["c", "d"],
  ]);
});

test("parse handles CRLF line endings", () => {
  assert.deepEqual(parse("a,b\r\nc,d"), [
    ["a", "b"],
    ["c", "d"],
  ]);
});

test("parse skips blank lines", () => {
  assert.deepEqual(parse("a,b\n\nc,d\n"), [
    ["a", "b"],
    ["c", "d"],
  ]);
});

test("parse on empty input yields no rows", () => {
  assert.deepEqual(parse(""), []);
});

