/**
 * Minimal CSV parsing for comma-separated data, with support for
 * double-quoted fields.
 */

/**
 * Split a single CSV line into fields.
 *
 * - Fields are separated by commas.
 * - Unquoted fields are trimmed of surrounding whitespace.
 * - A field that begins with `"` is quoted: its content is taken
 *   verbatim (embedded commas and whitespace are preserved), `""`
 *   represents one literal `"`, and the field ends at the next
 *   unescaped `"`.
 * - A `"` in the middle of an unquoted field is treated as literal.
 * - Malformed quoted fields throw an Error: an unterminated quote, or
 *   non-whitespace content after the closing quote.
 *
 * An empty line yields an empty array.
 */
export function parseLine(line: string): string[] {
  if (line === "") return [];

  const fields: string[] = [];
  let current = "";
  let inQuotes = false;
  let quoteClosed = false;
  let started = false;

  const pushField = (): void => {
    // Incidental whitespace after the closing quote is not data.
    fields.push(quoteClosed ? current.replace(/\s+$/, "") : current.trim());
    current = "";
    quoteClosed = false;
    started = false;
  };

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
          quoteClosed = true;
        }
      } else {
        current += ch;
      }
    } else if (ch === '"' && !started) {
      // Opening quote: discard incidental leading whitespace.
      current = "";
      inQuotes = true;
      started = true;
    } else if (ch === ",") {
      if (inQuotes) throw new Error(`Unterminated quoted field at column ${i + 1}`);
      pushField();
    } else {
      const isWhitespace = ch === " " || ch === "\t";
      if (!isWhitespace && quoteClosed) {
        throw new Error(`Unexpected content after closing quote at column ${i + 1}`);
      }
      if (!isWhitespace) started = true;
      current += ch;
    }
  }

  if (inQuotes) throw new Error("Unterminated quoted field at end of line");
  pushField();
  return fields;
}

/**
 * Parse CSV text into rows of fields.
 * Lines are separated by `\n` or `\r\n`; blank lines are skipped.
 */
export function parse(input: string): string[][] {
  return input
    .split(/\r?\n/)
