/**
 * Minimal CSV parsing for delimiter-separated data (RFC 4180-style),
 * with support for double-quoted fields.
 */

function assertDelimiter(delimiter: string): void {
  if (delimiter.length !== 1) {
    throw new Error(`delimiter must be a single character, got "${delimiter}"`);
  }
}

/**
 * Split one line into fields. Unquoted fields are split on `delimiter`
 * (default ","). Quoted fields (RFC 4180 style) preserve embedded
 * delimiters and doubled quotes (`""` -> `"`), and are split on the
 * delimiter only outside the quotes.
 */
export function parseLine(line: string, delimiter = ","): string[] {
  if (line === "") return [];
  assertDelimiter(delimiter);
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;
  let quoteClosed = false; // saw a quote inside an otherwise unquoted field
  let started = false; // seen a non-whitespace character in this field
  let quotedEnd = 0; // length of `current` at the closing quote of a quoted field

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i++; // skip the doubled quote
        } else {
          inQuotes = false;
          quotedEnd = current.length;
        }
      } else {
        current += ch;
      }
    } else if (ch === '"' && !started) {
      inQuotes = true;
    } else if (ch === delimiter) {
      const field = started ? current : current.trim();
      fields.push(quoteClosed ? current.slice(0, quotedEnd) : field);
      current = "";
      quoteClosed = false;
      started = false;
      quotedEnd = 0;
    } else {
      if (!started) started = true;
      if (ch !== " ") quoteClosed = false;
      current += ch;
    }
  }

  if (inQuotes) {
    throw new Error(`unterminated quoted field in line: ${JSON.stringify(line)}`);
  }
  if (current.trim() !== "") {
    const field = started ? current : current.trim();
    fields.push(quoteClosed ? current.slice(0, quotedEnd) : field);
  }

  if (quoteClosed && current.slice(quotedEnd).trim() !== "") {
    throw new Error(`unexpected content after closing quote in line: ${JSON.stringify(line)}`);
  }

  return fields;
}

