#!/usr/bin/env node
/**
 * Generate a large CSV file for benchmarking.
 *
 * Usage: node scripts/gen.ts [out.csv] [rows]
 *
 * Defaults: out = tmp/bench-200k.csv, rows = 200_000. Every row has 6
 * columns; some are quoted (embedded commas, doubled quotes) so the
 * full quote-handling path of the parser is exercised.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

const COLS = 6;

function makeRow(n: number): string {
  return `id_${n},${n},value_${n},"value, ${n}","value ""${n}""",end_${n}\n`;
}

function main(): void {
  const out = process.argv[2] ?? "tmp/bench-200k.csv";
  const rows = Number(process.argv[3] ?? 200_000);
  if (!Number.isInteger(rows) || rows <= 0) {
    console.error("rows must be a positive integer");
    process.exitCode = 1;
    return;
  }

  const parts: string[] = ["id,count,value,notes,tag,done\n"];
  for (let n = 0; n < rows; n++) parts.push(makeRow(n));
  const csv = parts.join("");

  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, csv);
  console.log(`wrote ${out}: ${rows} rows x ${COLS} cols, ${csv.length} chars`);
}

main();

#!/usr/bin/env node
/**
 * Time parse() on a generated CSV file.
 *
 * Usage: node scripts/bench.ts [file.csv] [runs]
 *
 * Defaults: file = tmp/bench-200k.csv, runs = 5. Reports the parse
 * time in milliseconds (min and average across runs).
 */
import { readFileSync } from "node:fs";
import { parse } from "../src/parse.ts";

function main(): void {
  const file = process.argv[2] ?? "tmp/bench-200k.csv";
  const runs = Number(process.argv[3] ?? 5);

  const r0 = process.hrtime.bigint();
  const text = readFileSync(file, "utf8");
  const readMs = Number(process.hrtime.bigint() - r0) / 1e6;

  const times: number[] = [];
  let rows: string[][] = [];
  for (let i = 0; i < runs; i++) {
    const t0 = process.hrtime.bigint();
    rows = parse(text);
    const t1 = process.hrtime.bigint();
    times.push(Number(t1 - t0) / 1e6);
  }

  const min = Math.min(...times);
  const avg = times.reduce((a, b) => a + b, 0) / times.length;

  console.log(`file:   ${file} (${(text.length / 1024 / 1024).toFixed(2)} MiB)`);
  console.log(`read:   ${readMs.toFixed(1)} ms`);
  console.log(
    `parse:  ${min.toFixed(1)} ms min of ${runs}, avg ${avg.toFixed(1)} ms` +
      ` (${rows.length - 1} data rows x ${rows[0].length} columns)`,
  );
}

main();

