export function parse(input: string, delimiter = ","): string[][] {
  assertDelimiter(delimiter);
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;
  let fieldIsQuoted = false;   // current field opened a quote
