      // outside quote, but field was quoted: only whitespace allowed
      if (ch !== " ") throw new Error(`Unexpected content after closing quote`);
      // skip: incidental trailing whitespace
    } else {
      field += ch;
      fieldTouched = true;
      lineNonEmpty = true;
    }
  }
  endRow();  // hmm — but at EOF need to throw if inQuotes still
