/**
 * Parse CSV text into rows of fields.
 *
 * - Fields are separated by `delimiter` (default ",").
 * - Lines are separated by `\n` or `\r\n` (a lone `\r` also terminates
 *   a line). Blank lines are skipped.
 * - A double quote at the start of a field (after any whitespace)
 *   starts a quoted field; embedded delimiters and newlines inside the
 *   quotes are preserved verbatim, and `""` represents a literal `"`.
 * - Surrounding whitespace on unquoted fields is trimmed; whitespace
 *   inside a quoted field is preserved as-is.
 * - Quotes in the middle of an unquoted field are kept as literal
 *   characters.
 *
 * Throws:
 * - Unterminated quoted field (no closing quote before end of input).
 * - Non-whitespace content after the closing quote of a quoted field.
 */
export function parse(input: string, delimiter = ","): string[][] {
  assertDelimiter(delimiter);

  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;
  let fieldIsQuoted = false;
  let fieldTouched = false;
  let lineNonEmpty = false;
  let quoteStart = -1;

  const pushField = (): void => {
    row.push(fieldIsQuoted ? field : field.trim());
    field = "";
    fieldIsQuoted = false;
    fieldTouched = false;
  };

  const endRow = (): void => {
    if (inQuotes) {
      throw new Error(`Unterminated quoted field at column ${quoteStart + 1}`);
    }
    pushField();
    if (lineNonEmpty) rows.push(row);
    row = [];
    lineNonEmpty = false;
  };

  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < input.length && input[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      lineNonEmpty = true;
    } else if (ch === '"' && !fieldTouched) {
      field = "";
      inQuotes = true;
      fieldIsQuoted = true;
      quoteStart = i;
      lineNonEmpty = true;
    } else if (ch === delimiter) {
      pushField();
      lineNonEmpty = true;
    } else if (ch === "\n" || ch === "\r") {
      endRow();
    } else if (fieldIsQuoted) {
      if (ch !== " ") {
        throw new Error(`Unexpected content after closing quote at column ${i + 1}`);
      }
    } else {
      if (ch !== " ") fieldTouched = true;
      field += ch;
      lineNonEmpty = true;
    }
  }

  endRow();
  return rows;
}

/**
 * Split a single CSV line into fields (no newlines in `line`).
 * See `parse` for the field rules.
 */
export function parseLine(line: string, delimiter = ","): string[] {
  if (line === "") return [];
  return parse(line, delimiter)[0];
}
