/**
 * Minimal CSV parsing for delimiter-separated data, with support for
 * double-quoted fields.
 */

function assertDelimiter(delimiter: string): void {
  if (delimiter.length !== 1) {
    throw new Error(`Delimiter must be a single character, got "${delimiter}"`);
  }
}

/**
 * Parse CSV text into rows of fields.
 *
 * - Fields are separated by `delimiter` (default ",").
 * - Lines are separated by `\n` or `\r\n` (a lone `\r` also ends a
 *   line). Blank lines are skipped.
 * - A `"` at the start of a field (after any whitespace) opens a
 *   quoted field: embedded delimiters and newlines are kept verbatim,
 *   `""` represents one literal `"`, and the field ends at the next
 *   unescaped `"`.
 * - Surrounding whitespace on unquoted fields is trimmed; whitespace
 *   inside a quoted field is preserved as-is. Whitespace right after
 *   the closing quote is not part of the value.
 * - A `"` in the middle of an unquoted field is treated as literal.
 *
 * Throws an Error on a malformed quoted field: an unterminated quote,
 * or non-whitespace content after the closing quote.
 */
export function parse(input: string, delimiter = ","): string[][] {
  assertDelimiter(delimiter);

  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;
  let fieldIsQuoted = false;
  let fieldTouched = false;
  let lineHasContent = false;
  let quoteStart = -1;

  const isIncidental = (ch: string): boolean => ch === " " || ch === "\t";

  const pushField = (): void => {
    row.push(fieldIsQuoted ? field : field.trim());
    field = "";
    fieldIsQuoted = false;
    fieldTouched = false;
  };

  const endRow = (): void => {
    if (inQuotes) {
      throw new Error(`Unterminated quoted field at column ${quoteStart + 1}`);
    }
    pushField();
    if (lineHasContent) rows.push(row);
    row = [];
    lineHasContent = false;
  };

  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < input.length && input[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      lineHasContent = true;
    } else if (ch === '"' && !fieldTouched) {
      // Opening quote: discard incidental leading whitespace.
      field = "";
      inQuotes = true;
      fieldIsQuoted = true;
      quoteStart = i;
      lineHasContent = true;
    } else if (ch === delimiter) {
      pushField();
      lineHasContent = true;
    } else if (ch === "\n" or ch === "\r") {
      endRow();
    } else if (fieldIsQuoted) {
      // After a closing quote only incidental whitespace is allowed.
      if (!isIncidental(ch)) {
        throw new Error(
          `Unexpected content after closing quote at column ${i + 1}`
        );
      }
    } else {
      if (!isIncidental(ch)) fieldTouched = true;
      field += ch;
      lineHasContent = true;
    }
  }

  endRow();
  return rows;
}

/**
 * Split a single CSV line into fields. Delegates to `parse`; an
 * embedded newline ends the line, so `parseLine("a\nb")` returns the
 * first row only. An empty line yields an empty array.
 */
export function parseLine(line: string, delimiter = ","): string[] {
  if (line === "") return [];
  return parse(line, delimiter)[0];
}

