/**
 * Minimal CSV serialization: the inverse of `parse` in `./parse.ts`.
 */

import { assertDelimiter } from "./parse.ts";

/**
 * Serialize a single field to CSV.
 *
 * The field is quoted when it contains the delimiter, a double quote,
 * or a newline (LF, CRLF, or lone CR); embedded quotes are doubled.
 * Any field that needs quoting is wrapped in double quotes, otherwise
 * it is written as-is.
 */
export function stringifyField(field: string, delimiter = ","): string {
  assertDelimiter(delimiter);
  if (
    !field.includes(delimiter) &&
    !field.includes('"') &&
    !field.includes("\n") &&
    !field.includes("\r")
  ) {
    return field;
  }
  let out = '"';
  for (let i = 0; i < field.length; i++) {
    const ch = field[i];
    out += ch === '"' ? '""' : ch;
  }
  return out + '"';
}

/**
 * Serialize rows to CSV text.
 *
 * Rows are joined with `\n` and the output ends with a trailing `\n`
 * (an empty rows list produces empty text). Each field is serialized
 * with `stringifyField`.
 *
 * Note: an empty row is written as a blank line, which `parse` skips,
 * so `parse(stringify(rows))` preserves rows only when every row has
 * at least one field.
 */
export function stringify(rows: string[][], delimiter = ","): string {
  assertDelimiter(delimiter);
  let out = "";
  for (const row of rows) {
    let line = "";
    for (let i = 0; i < row.length; i++) {
      if (i > 0) line += delimiter;
      line += stringifyField(row[i], delimiter);
    }
    out += line + "\n";
  }
  return out;
}

