#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { parse } from "./parse.ts";

const USAGE = "usage: node src/cli.ts [--delimiter <char>] <file.csv>";

interface CliOptions {
  file: string;
  delimiter: string;
}

/**
 * Parse argv (after `node src/cli.ts`). Supports `--delimiter <char>`
 * and `--delimiter=<char>`. Throws an Error on usage errors.
 */
function parseArgs(argv: string[]): CliOptions {
  let file = "";
  let delimiter = ",";
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--delimiter") {
      const value = argv[++i];
      if (value === undefined) throw new Error("--delimiter requires a value");
      delimiter = value;
    } else if (arg.startsWith("--delimiter=")) {
      delimiter = arg.slice("--delimiter=".length);
    } else if (arg.startsWith("-")) {
      throw new Error(`unknown option: ${arg}`);
    } else if (!file) {
      file = arg;
    } else {
      throw new Error(`unexpected argument: ${arg}`);
    }
  }
  if (!file) throw new Error("missing file argument");
  return { file, delimiter };
}

/**
 * Reads the CSV file named by the argument and prints it as a JSON
 * array of objects, using the first row as the header (object keys).
 * Missing fields become null; extra fields are ignored.
 */
function main(): void {
  let options: CliOptions;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error((err as Error).message);
    console.error(USAGE);
    process.exitCode = 1;
    return;
  }
  const { file, delimiter } = options;

  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch (err) {
    console.error(`error: cannot read ${file}: ${(err as Error).message}`);
    process.exitCode = 1;
    return;
  }

  let rows: string[][];
  try {
    rows = parse(text, delimiter);
  } catch (err) {
    console.error(`error: ${file}: ${(err as Error).message}`);
    process.exitCode = 1;
    return;
  }

  if (rows.length === 0) {
    console.log("[]");
    return;
  }

  const [header, ...data] = rows;
  const objects = data.map((fields) => {
    const obj: Record<string, string | null> = {};
    header.forEach((key, i) => {
      obj[key] = fields[i] ?? null;
    });
    return obj;
  });

  console.log(JSON.stringify(objects, null, 2));
}

main();

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

function runCli(...args: string[]): {
  status: number;
  stdout: string;
  stderr: string;
} {
  try {
    const stdout = execFileSync(process.execPath, ["src/cli.ts", ...args], {
      cwd: root,
      encoding: "utf8",
    });
    return { status: 0, stdout, stderr: "" };
  } catch (err) {
    const e = err as { status?: number; stdout?: string; stderr?: string };
    return {
      status: e.status ?? 1,
      stdout: e.stdout ?? "",
      stderr: e.stderr ?? "",
    };
  }
}

const expectedSemiRows = [
  { name: "Ada Lovelace", age: "36", notes: "Analytical Engine" },
  { name: "Smith; Jane", age: "29", notes: null },
];

test("cli converts a semicolon-delimited file using --delimiter", () => {
  const { status, stdout } = runCli("--delimiter", ";", "fixtures/sample-semi.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), expectedSemiRows);
});

test("cli accepts the --delimiter=<char> form", () => {
  const { status, stdout } = runCli("--delimiter=;", "fixtures/sample-semi.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), expectedSemiRows);
});

test("cli defaults to comma-delimited", () => {
  const { status, stdout } = runCli("fixtures/sample.csv");
  assert.equal(status, 0);
  assert.equal(JSON.parse(stdout)[0].name, "Ada Lovelace");
});

test("cli rejects a multi-character delimiter", () => {
  const { status, stderr } = runCli("--delimiter", ",,", "fixtures/sample.csv");
  assert.notEqual(status, 0);
  assert.match(stderr, /single character/);
});

test("cli prints [] and exits 0 for an empty file", () => {
  const { status, stdout } = runCli("fixtures/empty.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), []);
  assert.equal(stdout.trim(), "[]");
});

test("cli prints [] and exits 0 for a file with only blank lines", () => {
  const { status, stdout } = runCli("fixtures/blank-lines.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), []);
});

test("cli parses newlines inside quoted fields", () => {
  const { status, stdout } = runCli("fixtures/multiline.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { name: "Ada", notes: "line 1\nline 2" },
  ]);
});

