#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { parse } from "./parse.ts";

const USAGE = "usage: node src/cli.ts [--delimiter <char>] [--select <cols>] <file.csv>";

interface CliOptions {
  file: string;
  delimiter: string;
  select: string[] | null;
}

/**
 * Split a --select value into a list of column names. Entries are
 * trimmed; an empty entry (including an empty value) is a usage error.
 */
function parseSelect(value: string): string[] {
  const cols = value.split(",").map((c) => c.trim());
  if (cols.some((c) => c === "")) {
    throw new Error("--select requires a value");
  }
  return cols;
}

/**
 * Parse argv (after `node src/cli.ts`). Supports `--delimiter <char>`,
 * `--delimiter=<char>`, `--select <cols>`, and `--select=<cols>`.
 * Throws an Error on usage errors.
 */
function parseArgs(argv: string[]): CliOptions {
  let file = "";
  let delimiter = ",";
  let select: string[] | null = null;
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--delimiter") {
      const value = argv[++i];
      if (value === undefined) throw new Error("--delimiter requires a value");
      delimiter = value;
    } else if (arg.startsWith("--delimiter=")) {
      delimiter = arg.slice("--delimiter=".length);
    } else if (arg === "--select") {
      const value = argv[++i];
      if (value === undefined) throw new Error("--select requires a value");
      select = parseSelect(value);
    } else if (arg.startsWith("--select=")) {
      select = parseSelect(arg.slice("--select=".length));
    } else if (arg.startsWith("-")) {
      throw new Error(`unknown option: ${arg}`);
    } else if (!file) {
      file = arg;
    } else {
      throw new Error(`unexpected argument: ${arg}`);
    }
  }
  if (!file) throw new Error("missing file argument");
  return { file, delimiter, select };
}

/**
 * Reads the CSV file named by the argument and prints it as a JSON
 * array of objects, using the first row as the header (object keys).
 * Missing fields become null; extra fields are ignored. With
 * --select, only the listed columns are emitted, as object keys in
 * the order given; a column name not present in the header is an
 * error.
 */
function main(): void {
  let options: CliOptions;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error((err as Error).message);
    console.error(USAGE);
    process.exitCode = 1;
    return;
  }
  const { file, delimiter, select } = options;

  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch (err) {
    console.error(`error: cannot read ${file}: ${(err as Error).message}`);
    process.exitCode = 1;
    return;
  }

  let rows: string[][];
  try {
    rows = parse(text, delimiter);
  } catch (err) {
    console.error(`error: ${file}: ${(err as Error).message}`);
    process.exitCode = 1;
    return;
  }

  if (rows.length === 0) {
    console.log("[]");
    return;
  }

  const [header, ...data] = rows;

  let selected: { name: string; index: number }[] | null = null;
  if (select !== null) {
    const indexByName = new Map<string, number>();
    header.forEach((name, i) => {
      if (!indexByName.has(name)) indexByName.set(name, i);
    });
    const missing = select.find((name) => !indexByName.has(name));
    if (missing !== undefined) {
      console.error(`error: unknown column "${missing}"`);
      process.exitCode = 1;
      return;
    }
    selected = select.map((name) => ({ name, index: indexByName.get(name)! }));
  }

  const objects = data.map((fields) => {
    const obj: Record<string, string | null> = {};
    if (selected === null) {
      header.forEach((key, i) => {
        obj[key] = fields[i] ?? null;
      });
    } else {
      for (const { name, index } of selected) {
        obj[name] = fields[index] ?? null;
      }
    }
    return obj;
  });

  console.log(JSON.stringify(objects, null, 2));
}

main();

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

function runCli(...args: string[]): {
  status: number;
  stdout: string;
  stderr: string;
} {
  try {
    const stdout = execFileSync(process.execPath, ["src/cli.ts", ...args], {
