const INTEGER = /^-?\d+$/;
const DECIMAL = /^-?\d*\.\d+$/;

/**
 * Coerce a CSV field for `--types` output.
 *
 * Values that look like integers ("42", "-7") or plain decimals
 * ("3.14", ".5", "-.75") become JSON numbers; the bare lowercase
 * words "true" and "false" become JSON booleans. Everything else —
 * including empty strings, "+5", "1e5", "3.", "1,234", and case
 * variants like "True" — is left as a string.
 *
 * Numbers with more than 15 significant digits may lose precision
 * when converted (a 20-digit integer becomes a nearby float).
 */
export function coerceField(value: string): string | number | boolean {
  if (value === "true") return true;
  if (value === "false") return false;
  if (INTEGER.test(value) || DECIMAL.test(value)) return Number(value);
  return value;
}

