import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

function runCli(...args: string[]): {
  status: number;
  stdout: string;
  stderr: string;
} {
  try {
    const stdout = execFileSync(process.execPath, ["src/cli.ts", ...args], {
      cwd: root,
      encoding: "utf8",
    });
    return { status: 0, stdout, stderr: "" };
  } catch (err) {
    const e = err as { status?: number; stdout?: string; stderr?: string };
    return {
      status: e.status ?? 1,
      stdout: e.stdout ?? "",
      stderr: e.stderr ?? "",
    };
  }
}

const expectedSemiRows = [
  { name: "Ada Lovelace", age: "36", notes: "Analytical Engine" },
  { name: "Smith; Jane", age: "29", notes: null },
];

test("cli converts a semicolon-delimited file using --delimiter", () => {
  const { status, stdout } = runCli("--delimiter", ";", "fixtures/sample-semi.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), expectedSemiRows);
});

test("cli accepts the --delimiter=<char> form", () => {
  const { status, stdout } = runCli("--delimiter=;", "fixtures/sample-semi.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), expectedSemiRows);
});

test("cli defaults to comma-delimited", () => {
  const { status, stdout } = runCli("fixtures/sample.csv");
  assert.equal(status, 0);
  assert.equal(JSON.parse(stdout)[0].name, "Ada Lovelace");
});

test("cli rejects a multi-character delimiter", () => {
  const { status, stderr } = runCli("--delimiter", ",,", "fixtures/sample.csv");
  assert.notEqual(status, 0);
  assert.match(stderr, /single character/);
});

test("cli prints [] and exits 0 for an empty file", () => {
  const { status, stdout } = runCli("fixtures/empty.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), []);
  assert.equal(stdout.trim(), "[]");
});

test("cli prints [] and exits 0 for a file with only blank lines", () => {
  const { status, stdout } = runCli("fixtures/blank-lines.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), []);
});

test("cli parses newlines inside quoted fields", () => {
  const { status, stdout } = runCli("fixtures/multiline.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { name: "Ada", notes: "line 1\nline 2" },
  ]);
});

test("cli --select keeps only the selected columns in the given order", () => {
  const { status, stdout } = runCli("--select", "notes,name", "fixtures/sample.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { notes: "Analytical Engine", name: "Ada Lovelace" },
    { notes: 'Compiles "Fleet" for the COBOL era', name: "Grace Hopper" },
    { notes: null, name: "Smith, Jane" },
  ]);
  assert.ok(stdout.indexOf('"notes"') < stdout.indexOf('"name"'));
});

test("cli --select can pick a single column", () => {
  const { status, stdout } = runCli("--select", "name", "fixtures/sample.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { name: "Ada Lovelace" },
    { name: "Grace Hopper" },
    { name: "Smith, Jane" },
  ]);
});

test("cli accepts the --select=<cols> form", () => {
  const { status, stdout } = runCli("--select=age", "fixtures/sample.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [{ age: "36" }, { age: "48" }, { age: "29" }]);
});

test("cli --select trims whitespace around column names", () => {
  const { status, stdout } = runCli("--select", " notes , name ", "fixtures/sample.csv");
  assert.equal(status, 0);
  assert.deepEqual(Object.keys(JSON.parse(stdout)[0]), ["notes", "name"]);
});

test("cli --select with an unknown column fails", () => {
  const { status, stderr } = runCli("--select", "nope", "fixtures/sample.csv");
  assert.notEqual(status, 0);
  assert.match(stderr, /unknown column "nope"/);
});

test("cli --select without a value is a usage error", () => {
  const { status, stderr } = runCli("fixtures/sample.csv", "--select");
  assert.notEqual(status, 0);
  assert.match(stderr, /--select requires a value/);
});

test("cli --select works with a custom delimiter", () => {
  const { status, stdout } = runCli(
    "--delimiter", ";", "--select", "notes,name", "fixtures/sample-semi.csv"
  );
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { notes: "Analytical Engine", name: "Ada Lovelace" },
    { notes: null, name: "Smith; Jane" },
  ]);
});

test("cli --select on an empty file prints []", () => {
  const { status, stdout } = runCli("--select", "name", "fixtures/empty.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), []);
});

test("cli --types converts integers, decimals, and booleans", () => {
  const { status, stdout } = runCli("--types", "fixtures/typed.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { name: "Ada", age: 36, score: 9.5, active: true },
    { name: "Grace", age: 48, score: 0.75, active: false },
    { name: "Maverick", age: "", score: 3.14, active: "TRUE" },
  ]);
});

test("cli leaves fields as strings without --types", () => {
  const { status, stdout } = runCli("fixtures/typed.csv");
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { name: "Ada", age: "36", score: "9.5", active: "true" },
    { name: "Grace", age: "48", score: ".75", active: "false" },
    { name: "Maverick", age: "", score: "3.14", active: "TRUE" },
  ]);
});

test("cli --types combines with --select", () => {
  const { status, stdout } = runCli(
    "--select", "active,age", "--types", "fixtures/typed.csv"
  );
  assert.equal(status, 0);
  assert.deepEqual(JSON.parse(stdout), [
    { active: true, age: 36 },
    { active: false, age: 48 },
    { active: "TRUE", age: "" },
  ]);
});

