test("parse handles a single line with no newline at all", () => {
  assert.deepEqual(parse("a,b"), [["a", "b"]]);
});

test("parseLine splits on a custom delimiter", () => {
  assert.deepEqual(parseLine("a;b;c", ";"), ["a", "b", "c"]);
});

test("custom delimiter works with quoted fields", () => {
  assert.deepEqual(parseLine('"a;b";c', ";"), ["a;b", "c"]);
});

test("parse splits rows on a custom delimiter", () => {
  assert.deepEqual(parse("a;b\nc;d", ";"), [
    ["a", "b"],
    ["c", "d"],
  ]);
});

test("a multi-character delimiter is rejected", () => {
  assert.throws(() => parseLine("a,,b", ",,"), /single character/);
  assert.throws(() => parse("a,,b", ",,"), /single character/);
});

